class Solution {
  private final int[] cnt = new int[32];

  private int height(TreeNode node) {
    if (node == null) return 0;
    int l = height(node.left), r = height(node.right);
    if (l < 0 || l != r) return -1;
    cnt[l + 1]++;
    return l + 1;
  }

  public int kthLargestPerfectSubtree(TreeNode root, int k) {
    height(root);
    for (int h = 31; h >= 1; h--) {
      k -= cnt[h];
      if (k <= 0) return (1 << h) - 1;
    }
    return -1;
  }
}
